mapper.select:
SELECT f.family_id, f.family_name, f.relation, f.birth_date, CASE WHEN f.relation = 'LINEAL_DESCENDANT' AND TIMESTAMPDIFF(YEAR, f.birth_date, #{baseDate}) < 19 THEN 1 ELSE 0 END AS is_minor, l.deduction_limit, COALESCE(SUM(CASE WHEN g.status = 'COMPLETED' THEN g.amount END), 0) AS used_amount, COALESCE(SUM(CASE WHEN g.status = 'PLANNED' THEN g.amount END), 0) AS planned_amount, COUNT(CASE WHEN g.status = 'COMPLETED' THEN 1 END) AS aggregated_count, MIN(CASE WHEN g.status = 'COMPLETED' THEN g.gift_date END) AS oldest_gift_date FROM family f LEFT JOIN gift g ON g.family_id = f.family_id AND g.gift_date >= #{windowStartDate} AND g.gift_date <= #{baseDate}
AND g.gift_id != #{excludeGiftId}
LEFT JOIN gift_deduction_limit l ON l.relation = f.relation AND l.is_minor = CASE WHEN f.relation = 'LINEAL_DESCENDANT' AND TIMESTAMPDIFF(YEAR, f.birth_date, #{baseDate}) < 19 THEN 1 ELSE 0 END AND l.effective_from <= #{baseDate} AND (l.effective_to IS NULL OR l.effective_to > #{baseDate}) WHERE f.user_id = #{userId}
AND f.family_id = #{familyId}
GROUP BY f.family_id, f.family_name, f.relation, f.birth_date, l.deduction_limit ORDER BY f.family_id

SELECT

FROM gift g
JOIN family f on f.family_id = g.family_id
WHERE f.user_id = #{userId}
AND g.status = 'COMPLETED'
AND g.gift_date >= #{windowStartDate}
AND g.gift_date <= #{baseDate}

    AND g.family_id = #{familyId}

ORDER BY g.family_id, g.gift_date, g.gift_id

SELECT COUNT(*)
FROM gift
WHERE family_id = #{familyId}

SELECT deduction_limit
FROM gift_deduction_limit
WHERE relation = #{relation}
AND is_minor = #{minor}
AND effective_from <= #{baseDate}
AND (effective_to IS NULL OR effective_to > #{baseDate})
ORDER BY effective_from DESC
LIMIT 1

SELECT COUNT(*)
FROM gift
WHERE simul_result_id = #{simulResultId}
